def axis(
    *,
    data: Any = None,
    field: Any = None,
    format: Any = None,
    label: Any = None,
    line: Any = None,
    orient: Any = None,
    prefix: Any = None,
    scale: Any = None,
    suffix: Any = None,
    ticks: Any = None,
    type: Any = None,
) -> Node:
    """An axis for a scale: tick labels, tick marks and a domain line. Labels never pile up: a
    horizontal numeric axis asks for as many ticks as its measured labels fit; category names
    wrap in their band, turn 45° when a word is wider than the band, and leave out every k-th
    name only when even that doesn't fit.

    Recipe ``@datars/std/axis``.

    Parameters
    ----------
    data : str | DataFrame | Data
        The table a band scale's categories come from (with `field`): their names are measured,
        so a horizontal axis wraps, turns or leaves out labels only as they need.
    field : str
        The categories' field in `data`.
    format : str
        Number format for labels (d3-format).
    label : str
        Axis title.
    line : bool, default True
        Draw the domain line.
    orient : "left" | "bottom" | "right" | "top", default "left"
    prefix : str
        Before each number label ('$').
    scale : str, default "y"
        The scale to draw.
    suffix : str
        After it ('M', ' kr').
    ticks : float, default 0
        Tick count hint (0 = automatic: from the axis length, and across, from how many of its
        measured labels fit).
    type : str
        The scale's type (`linear`, `log`, `time`, …; the plot passes it). A horizontal numeric
        axis fits its tick count to its labels' measured width.

    Theme tokens: ``muted``, ``rule``, ``size.label``.
    """
    return use('@datars/std/axis', locals(), RENAMES['axis'])


RENAMES['axis'] = {}


