def cloud(
    *,
    data: Any = None,
    x: Any = None,
    y: Any = None,
    bbox: Any = None,
    budget: Any = None,
    children: Any = None,
    explore: Any = None,
    fill: Any = None,
    glow: Any = None,
    glow_opacity: Any = None,
    glow_points: Any = None,
    label: Any = None,
    max_zoom: Any = None,
    name: Any = None,
    opacity: Any = None,
    padding: Any = None,
    points: Any = None,
    r: Any = None,
) -> Node:
    """A point cloud of any size (millions of rows): dots at their own x/y in an explorable view —
    a density-preserving sample at every zoom, every row up close, a tooltip on each.

    Recipe ``@datars/std/cloud``.

    Parameters
    ----------
    bbox : object
        The extent to frame, [x0, y0, x1, y1] in the rows' units. Default: the rows' extent —
        give it for millions of rows (finding it reads them all) and for point archives.
    budget : float, default 2048
        Rows per tile of the index at average density (smaller: lighter tiles, more of them).
    children : list[Node]
        Drawn over the dots, in the same coordinates (annotations, marks).
    data : str | DataFrame | Data
        A table, or a point archive (a `tiles` source the publish compiler wrote).
    explore : str, default "cloud"
        The signals the camera explores with (`<explore>.x`, `.y`, `.zoom`).
    fill : value | Expr
        Dot ink, or an expression over the row (default $mark).
    glow : value | Expr
        Radius (px) of a glow under the dots (a number or an expression over the row): a sample
        drawn large and faint, so density reads at a glance and, up close, stars bloom. None by
        default.
    glow_opacity : value | Expr
        The glow's opacity per dot: a number (default 0.05) or an expression over the row
        (weight bright rows). (``glowOpacity``)
    glow_points : float, default 6000
        How many dots the glow draws at most. (``glowPoints``)
    label : value | Expr
        Tooltip and accessible name per row (default `x, y`).
    max_zoom : float, default 2048
        How far in the reader can zoom, × the whole. (``maxZoom``)
    name : str
        What the rows are, for the accessible description ('4,000,000 stars').
    opacity : value | Expr
        Per-dot opacity: an expression over the row.
    padding : float, default 12
    points : float, default 150000
        The most dots a frame draws: a view holding more shows a uniform sample this size, one
        holding fewer shows every row.
    r : value | Expr
        Dot radius in screen px: a number, or an expression over the row.
    x : str
    y : str

    Theme tokens: ``mark``.
    """
    return use('@datars/std/cloud', locals(), RENAMES['cloud'])


RENAMES['cloud'] = {"glow_opacity": "glowOpacity", "glow_points": "glowPoints", "max_zoom": "maxZoom"}


